# frozen_string_literal: true

require "rails_helper"

# The reply-language directive (AD-16's one-parameter policy, owner bug round
# 2026-11-15): every builder's language line is generated by the ONE
# language_directive helper, and the vocabulary now carries the traditional-
# Chinese UI locale ("zh-TW") alongside zh/en — the directive must name the
# SCRIPT (繁體中文), not fall through to English.
RSpec.describe "Ai::Prompts language directive" do
  let(:context) do
    Struct.new(:text, :truncated).new("The QUIC transport protocol.", false)
  end

  it "names 简体中文 for zh" do
    prompt = Ai::Prompts.quiz(mode: "open", language: "zh", context: context).join("\n")
    expect(prompt).to include("Write every user-facing string in 简体中文.")
  end

  it "names 繁體中文 for zh-TW — the script, never a fallthrough to English" do
    prompt = Ai::Prompts.quiz(mode: "open", language: "zh-TW", context: context).join("\n")
    expect(prompt).to include("Write every user-facing string in 繁體中文.")
    expect(prompt).not_to include("Write every user-facing string in English.")
  end

  it "names English for en" do
    prompt = Ai::Prompts.quiz(mode: "open", language: "en", context: context).join("\n")
    expect(prompt).to include("Write every user-facing string in English.")
  end

  it "accepts zh-TW wherever the vocabulary validates (Ai::LANGUAGES)" do
    expect(Ai::LANGUAGES).to contain_exactly("zh", "en", "zh-TW")
  end
end
